WITH cleaned AS (SELECT *, status_bits + humidity AS status_bits_plus_humidity FROM device_readings WHERE status_bits <> 9), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), sessions_device_readings AS (SELECT id, device_code, reading_ts, pressure, firmware, status_bits_plus_humidity, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, SIZE(COLLECT_SET(device_code)) AS num_device_codes, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count FROM sessions_device_readings GROUP BY 1;
